\begin{align*} x_A &= r_A \cos \theta_A = 2 \cos 70^\circ \\ y_A &= r_A \sin \theta_A = 2 \sin 70^\circ \\ x_B &= r_B \cos \theta_B = 2\sqrt{3} \cos 40^\circ \\ y_B &= r_B \sin \theta_B = 2\sqrt{3} \sin 40^\circ \\ x_C &= r_C \cos \theta_C = 3 \cos 10^\circ \\ y_C &= r_C \sin \theta_C = 3 \sin 10^\circ \end{align*}Then the area of triangle $ABC$ is given by
\begin{align*} \frac{1}{2} |(x_A - x_C)(y_B - y_A) - (x_A - x_B)(y_C - y_A)| &= \frac{1}{2} |(2 \cos 70^\circ - 3 \cos 10^\circ)(2\sqrt{3} \sin 40^\circ - 2 \sin 70^\circ) - (2 \cos 70^\circ - 2\sqrt{3} \cos 40^\circ)(3 \sin 10^\circ - 2 \sin 70^\circ)| \\ &= \frac{1}{2} |(2 \cos 70^\circ - 3 \cos 10^\circ)(2\sqrt{3} \sin 40^\circ - 2 \sin 70^\circ) - (2 \cos 70^\circ - 2\sqrt{3} \cos 40^\circ)(3 \sin 10^\circ - 2 \sin 70^\circ)| \\ &= \frac{1}{2} |4\sqrt{3} \cos 70^\circ \sin 40^\circ - 4 \cos 70^\circ \sin 70^\circ - 6\sqrt{3} \cos 10^\circ \sin 40^\circ + 6 \cos 10^\circ \sin 70^\circ \\ &\quad - (6 \cos 70^\circ \sin 10^\circ - 4 \cos 70^\circ \sin 70^\circ - 6\sqrt{3} \cos 40^\circ \sin 10^\circ + 4\sqrt{3} \cos 40^\circ \sin 70^\circ)| \\ &= \frac{1}{2} |4\sqrt{3} \cos 70^\circ \sin 40^\circ - 4 \cos 70^\circ \sin 70^\circ - 6\sqrt{3} \cos 10^\circ \sin 40^\circ + 6 \cos 10^\circ \sin 70^\circ \\ &\quad - 6 \cos 70^\circ \sin 10^\circ + 4 \cos 70^\circ \sin 70^\circ + 6\sqrt{3} \cos 40^\circ \sin 10^\circ - 4\sqrt{3} \cos 40^\circ \sin 70^\circ| \\ &= \frac{1}{2} |4\sqrt{3} (\cos 70^\circ \sin 40^\circ - \cos 40^\circ \sin 70^\circ) - 6\sqrt{3} (\cos 10^\circ \sin 40^\circ - \cos 40^\circ \sin 10^\circ) + 6(\cos 10^\circ \sin 70^\circ - \cos 70^\circ \sin 10^\circ)| \\ &= \frac{1}{2} |4\sqrt{3} \sin (40^\circ - 70^\circ) - 6\sqrt{3} \sin (40^\circ - 10^\circ) + 6 \sin (70^\circ - 10^\circ)| \\ &= \frac{1}{2} |4\sqrt{3} \sin (-30^\circ) - 6\sqrt{3} \sin 30^\circ + 6 \sin 60^\circ| \\ &= \frac{1}{2} |4\sqrt{3} (-\frac{1}{2}) - 6\sqrt{3} (\frac{1}{2}) + 6 (\frac{\sqrt{3}}{2})| \\ &= \frac{1}{2} |-2\sqrt{3} - 3\sqrt{3} + 3\sqrt{3}| \\ &= \frac{1}{2} |-2\sqrt{3}| \\ &= \frac{1}{2} (2\sqrt{3}) \\ &= \sqrt{3} \end{align*}

